log-to-eventhub:
@{
    var jwt = context.Variables.GetValueOrDefault<Jwt>("jwt");
    var oid = jwt != null ? jwt.Claims.GetValueOrDefault("oid", "") : "";
    var caller = (string)JObject.Parse("{{caller-labels}}")[oid] ?? "other";
    var label = context.Response.Headers.GetValueOrDefault("x-releaselens-backend", "");
    string answered = (label == "primary" || label == "secondary") ? label : null;
    int status = context.Response.StatusCode;
    bool refused = answered == null && (status == 401 || status == 403 || status == 429);
    var consumed = context.Variables.GetValueOrDefault<object>("tokensConsumed");
    int? tokens = answered == null || consumed == null ? (int?)null : Convert.ToInt32(consumed);
    return new JObject(
        new JProperty("event_time", context.Timestamp.ToUniversalTime().ToString("yyyy-MM-dd'T'HH:mm:ss.fff'Z'")),
        new JProperty("request_id", context.RequestId.ToString()),
        new JProperty("session", "{{p10-session}}"),
        new JProperty("api", context.Api.Name),
        new JProperty("operation", context.Operation.Id),
        new JProperty("caller", caller),
        new JProperty("answered_by", answered),
        new JProperty("status", status),
        new JProperty("refused_by_gateway", refused),
        new JProperty("tokens", tokens),
        new JProperty("latency_ms", (int)context.Elapsed.TotalMilliseconds)
    ).ToString(Newtonsoft.Json.Formatting.None);
}
